package com.bhagya.qa.performance;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public class LoadTestEngine { public PerformanceResult execute(String baseUrl,int users,int perUser,String scenario)throws Exception{if(users<1||users>200||perUser<1||perUser>1000)throw new IllegalArgumentException("users 1-200 and requestsPerUser 1-1000");HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();ExecutorService pool=Executors.newFixedThreadPool(users);List<Long>lat=Collections.synchronizedList(new ArrayList<>());AtomicInteger ok=new AtomicInteger(),bad=new AtomicInteger();long start=System.nanoTime();List<Future<?>>jobs=new ArrayList<>();for(int u=0;u<users;u++)jobs.add(pool.submit(()->{for(int i=0;i<perUser;i++){long t=System.nanoTime();try{HttpRequest req=HttpRequest.newBuilder(URI.create(baseUrl+"/api/products")).timeout(Duration.ofSeconds(5)).GET().build();HttpResponse<String>res=client.send(req,HttpResponse.BodyHandlers.ofString());lat.add(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-t));if(res.statusCode()>=200&&res.statusCode()<400)ok.incrementAndGet();else bad.incrementAndGet();}catch(Exception ex){lat.add(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-t));bad.incrementAndGet();}}}));for(Future<?>j:jobs)j.get();pool.shutdown();long duration=Math.max(1,TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start));List<Long>sorted=new ArrayList<>(lat);Collections.sort(sorted);int total=ok.get()+bad.get();return new PerformanceResult(scenario,users,total,ok.get(),bad.get(),duration,pct(sorted,50),pct(sorted,95),pct(sorted,99),total*1000.0/duration,total==0?0:bad.get()*100.0/total);}private long pct(List<Long>a,double p){if(a.isEmpty())return 0;return a.get(Math.max(0,Math.min((int)Math.ceil(p/100*a.size())-1,a.size()-1)));}}
